diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 77b0c66..35045f7 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1853,6 +1853,77 @@ void process_dump(des_proc* p, log_sev sev)


 // ( SOLUZIONE 2025-06-05
+extern "C" bool c_swap_out(natl pid, char *buf)
+{
+	if (pid > MAX_PROC_ID)
+		return false;
+
+	des_proc* p = proc_table[pid];
+
+	if (!p)
+		return false;
+
+	if (p->livello == LIV_SISTEMA || p == esecuzione) {
+		c_abort_p();
+		return false;
+	}
+
+	if (p->swapped_out)
+		return false;
+
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, true, false)) {
+		c_abort_p();
+		return false;
+	}
+
+	paddr pstack = trasforma(p->cr3, fin_utn_p - 1) + 1;
+	memcpy(buf, voidptr_cast(pstack - DIM_USR_STACK), DIM_USR_STACK);
+
+	distruggi_pila(p->cr3, fin_utn_p, DIM_USR_STACK);
+	p->swapped_out = true;
+	p->scheduled = false;
+
+	return true;
+}
+
+extern "C" bool c_swap_in(natl pid, const char *buf)
+{
+	if (pid > MAX_PROC_ID)
+		return false;
+
+	des_proc* p = proc_table[pid];
+
+	if (!p)
+		return false;
+
+	if (p->livello == LIV_SISTEMA) {
+		c_abort_p();
+		return false;
+	}
+
+	if (!p->swapped_out)
+		return false;
+
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, false, false)) {
+		c_abort_p();
+		return false;
+	}
+
+	if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE))
+		return false;
+
+	paddr pstack = trasforma(p->cr3, fin_utn_p - 1) + 1;
+	memcpy(voidptr_cast(pstack - DIM_USR_STACK), buf, DIM_USR_STACK);
+
+	p->swapped_out = false;
+
+	if (p->scheduled) {
+		p->scheduled = false;
+		inserimento_lista(pronti, p);
+	}
+
+	return true;
+}
 //   SOLUZIONE 2025-06-05 )


